import { chromium, expect } from "@playwright/test";
import { mkdir } from "node:fs/promises";
const output = "/tmp/tape-speaker-identity-components/screenshots";
await mkdir(output, { recursive: true });
const browser = await chromium.launch({ headless: true, channel: "chrome" });
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
const errors = [];
page.on("pageerror", error => errors.push(error.message));
await page.goto("http://127.0.0.1:8781");
await expect(page.getByRole("button", { name: "Rename Alex everywhere" })).toHaveCount(2);
await page.getByRole("button", { name: "Rename Alex everywhere" }).first().click();
await page.getByLabel("Speaker name").fill("alex@example.test");
await page.getByRole("option", { name: /Alex Quinn.*alex@example.test/ }).click();
await page.getByLabel("Speaker name").fill("Alex Q");
await expect(page.getByText(/Linked to Alex Quinn/)).toBeVisible();
await page.screenshot({ path: `${output}/desktop.png`, fullPage: true });
await page.setViewportSize({ width: 390, height: 844 });
await page.screenshot({ path: `${output}/mobile.png`, fullPage: true });
await expect.poll(() => page.evaluate(() => document.documentElement.scrollWidth <= innerWidth)).toBe(true);
await page.getByRole("button", { name: "Save speaker" }).click();
await page.getByRole("button", { name: "Rename Alex Q everywhere" }).click();
await expect(page.getByText(/Linked to Alex Q/)).toBeVisible();
await expect(page.getByRole("button", { name: "Rename Alex everywhere" })).toHaveCount(1);
if (errors.length) throw new Error(errors.join("\n"));
await browser.close();
console.log(`Speaker identity browser checks passed. Screenshots: ${output}`);
